cd /workspace/submission/infra && cat > network.tf <<'EOF'
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = { Name = "${local.prefix}-vpc" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags                    = { Name = "${local.prefix}-public-${count.index == 0 ? "a" : "b"}", Tier = "public" }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags                    = { Name = "${local.prefix}-private-${count.index == 0 ? "a" : "b"}", Tier = "private" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.prefix}-igw" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.prefix}-public-rt" }

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.prefix}-private-rt" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Rules are declared inline so that Terraform is authoritative
# over the complete rule set and removes out-of-band additions on every apply.
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB"
  vpc_id      = aws_vpc.main.id
  tags        = { Name = "${local.prefix}-alb" }

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to ECS tasks inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks"
  vpc_id      = aws_vpc.main.id
  tags        = { Name = "${local.prefix}-ecs" }

  ingress {
    description     = "API port from the ALB only"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "PostgreSQL inside the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Valkey inside the VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "AWS control plane / service endpoints (HTTPS)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Local AWS control plane endpoint"
    from_port   = 4566
    to_port     = 4566
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL"
  vpc_id      = aws_vpc.main.id
  tags        = { Name = "${local.prefix}-rds" }

  ingress {
    description     = "PostgreSQL from ECS tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey cache"
  vpc_id      = aws_vpc.main.id
  tags        = { Name = "${local.prefix}-valkey" }

  ingress {
    description     = "Valkey from ECS tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []
}
EOF
cat > kms.tf <<'EOF'
locals {
  kms_usages = toset(["database", "messaging", "projection", "audit"])
}

resource "aws_kms_key" "this" {
  for_each                = local.kms_usages
  description             = "ClearLedger ${each.key} key (${local.prefix})"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = {
    Name                = "${local.prefix}-${each.key}"
    ClearLedgerKeyUsage = each.key
  }
}

resource "aws_kms_alias" "this" {
  for_each      = local.kms_usages
  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}
EOF
cat > logs.tf <<'EOF'
locals {
  log_groups = {
    api       = "/clearledger/${local.prefix}/api"
    projector = "/clearledger/${local.prefix}/projector"
    relay     = "/clearledger/${local.prefix}/outbox-relay"
    archiver  = "/clearledger/${local.prefix}/audit-archiver"
  }
}

resource "aws_cloudwatch_log_group" "this" {
  for_each          = local.log_groups
  name              = each.value
  retention_in_days = 14
  tags              = { Name = "${local.prefix}-${each.key}-logs" }
}
EOF

cd /workspace/submission/infra && cat > data.tf <<'EOF'
# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.prefix}-db"
  subnet_ids = aws_subnet.private[*].id
  tags       = { Name = "${local.prefix}-db" }
}

resource "aws_db_instance" "main" {
  identifier             = "${local.prefix}-db"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = local.cfg.db_name
  username               = local.cfg.db_username
  password               = local.cfg.db_password
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  apply_immediately      = true
  multi_az               = false

  tags = { Name = "${local.prefix}-db" }

  lifecycle {
    ignore_changes = [engine_version]
  }
}

locals {
  db_url = "postgres://${urlencode(local.cfg.db_username)}:${urlencode(local.cfg.db_password)}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.cfg.db_name}"
}

# ---------------------------------------------------------------------------
# DynamoDB projection store
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = { Name = "${local.prefix}-projections" }
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.prefix}-cache"
  subnet_ids = aws_subnet.private[*].id
  tags       = { Name = "${local.prefix}-cache" }
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id = "${local.prefix}-valkey"
  description          = "ClearLedger projection cache"
  engine               = "valkey"
  engine_version       = "8.0"
  node_type            = "cache.t4g.micro"
  num_cache_clusters   = 1
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.main.name
  security_group_ids   = [aws_security_group.valkey.id]

  automatic_failover_enabled = false
  multi_az_enabled           = false
  apply_immediately          = true

  tags = { Name = "${local.prefix}-valkey" }
}

locals {
  valkey_endpoint = aws_elasticache_replication_group.valkey.primary_endpoint_address
  valkey_port     = aws_elasticache_replication_group.valkey.port
  valkey_url      = "redis://${local.valkey_endpoint}:${local.valkey_port}"
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-ledger-audit"
  force_destroy = true
  tags          = { Name = "${local.prefix}-ledger-audit" }
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id

  rule {
    bucket_key_enabled = true
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600
  tags                      = { Name = "${local.prefix}-events-dlq" }
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = { Name = "${local.prefix}-events" }
}

# ---------------------------------------------------------------------------
# Cognito
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = "${local.prefix}-users"
  tags = { Name = "${local.prefix}-users" }
}

resource "aws_cognito_resource_server" "main" {
  user_pool_id = aws_cognito_user_pool.main.id
  identifier   = "clearledger"
  name         = "${local.prefix}-clearledger"

  scope {
    scope_name        = "read"
    scope_description = "Read settlements and ledgers"
  }
  scope {
    scope_name        = "write"
    scope_description = "Create settlements and append entries"
  }
  scope {
    scope_name        = "admin"
    scope_description = "Administrative projection rebuilds"
  }
}

resource "aws_cognito_user_pool_client" "this" {
  for_each     = toset(["read", "write", "admin"])
  name         = "${local.prefix}-${each.key}"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/${each.key}"]
  supported_identity_providers         = ["COGNITO"]

  depends_on = [aws_cognito_resource_server.main]
}

locals {
  issuer_url     = "${local.runtime_aws_ep}/${aws_cognito_user_pool.main.id}"
  jwks_url       = "${local.runtime_aws_ep}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"
  token_endpoint = "${local.runtime_aws_ep}/cognito-idp/oauth2/token"
  auth_audiences = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.this[k].id])
}
EOF

cd /workspace/submission/infra && cat > iam.tf <<'EOF'
locals {
  kms_arn = { for k, v in aws_kms_key.this : k => v.arn }
  all_kms = [for k in ["database", "messaging", "projection", "audit"] : local.kms_arn[k]]

  q_main  = aws_sqs_queue.main.arn
  q_dlq   = aws_sqs_queue.dlq.arn
  queues  = [local.q_main, local.q_dlq]
  tbl     = aws_dynamodb_table.projections.arn
  tbl_idx = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  tables  = [local.tbl, local.tbl_idx]
  bkt     = aws_s3_bucket.audit.arn
  bkt_all = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]

  # Log group ARNs (group itself and its streams) per workload.
  lg = {
    for k, v in aws_cloudwatch_log_group.this : k => [v.arn, "${v.arn}:*"]
  }
  lg_others = {
    for k in keys(local.log_groups) :
    k => flatten([for o in keys(local.log_groups) : local.lg[o] if o != k])
  }

  logs_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]

  fn_arn = {
    projector = "arn:aws:lambda:${local.region}:${local.account_id}:function:${local.prefix}-projector"
    relay     = "arn:aws:lambda:${local.region}:${local.account_id}:function:${local.prefix}-outbox-relay"
    archiver  = "arn:aws:lambda:${local.region}:${local.account_id}:function:${local.prefix}-audit-archiver"
  }

  deny_key_lifecycle = {
    Sid      = "DenyKeyLifecycle"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_kms
  }

  roles = {
    ecs_execution = { name = "${local.prefix}-ecs-execution", principal = "ecs-tasks.amazonaws.com" }
    ecs_task      = { name = "${local.prefix}-ecs-task", principal = "ecs-tasks.amazonaws.com" }
    projector     = { name = "${local.prefix}-projector", principal = "lambda.amazonaws.com" }
    relay         = { name = "${local.prefix}-relay", principal = "lambda.amazonaws.com" }
    archiver      = { name = "${local.prefix}-archiver", principal = "lambda.amazonaws.com" }
    scheduler     = { name = "${local.prefix}-scheduler", principal = "scheduler.amazonaws.com" }
  }

  policies = {
    ecs_execution = [
      {
        Sid      = "WriteOwnLogs"
        Effect   = "Allow"
        Action   = local.logs_actions
        Resource = local.lg.api
      },
      local.deny_key_lifecycle,
      {
        Sid      = "DenySqs"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = local.queues
      },
      {
        Sid      = "DenyDynamoDb"
        Effect   = "Deny"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
        Resource = local.tables
      },
      {
        Sid      = "DenyS3"
        Effect   = "Deny"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
        Resource = local.bkt_all
      },
      {
        Sid      = "DenyKmsUse"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = local.all_kms
      },
      {
        Sid      = "DenyForeignLogs"
        Effect   = "Deny"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = local.lg_others.api
      },
    ]

    ecs_task = [
      {
        Sid      = "PublishEvents"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
